import { Group, PlaneGeometry, Box3, Vector3, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv, mix, color, vec2, dot, sin, fract, float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'kinetic-3d-headline';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const find = (role, fallback) => {
    const hit = items.find((i) => i.role === role);
    return hit ? hit.text : fallback;
  };
  const captionStr = find('caption', 'NOVA ATELIER / CALIBRE PROGRAM');
  const heroStr = find('hero', 'TIME, MACHINED.');
  const subheadStr = find('subhead', 'Every calibre begins as a solid billet.');

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#101017', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#13131a' }],
  };

  const cleanupFns = [];
  const timelines = [];

  // ---------- BACKDROP ----------
  const gTop = color(colors.gradientStops[1]?.hex ?? '#13131a');
  const gBottom = color(colors.gradientStops[0]?.hex ?? '#0b0b10');
  const uvNode = uv();
  const grainSeed = dot(uvNode.mul(vec2(1024.0, 768.0)), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainAmt = grain.sub(0.5).mul(0.015);
  const backdropColorNode = mix(gBottom, gTop, uvNode.y).add(grainAmt);

  const backdropGeo = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = backdropColorNode;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // ---------- HELPERS ----------
  // fontAtlas convention observed: fontSize(px)/100 -> scene-unit em height @ scale 1.
  // Uniform 0.5 scale maps spec fontSizes to the requested scene-unit em heights.
  const TEXT_SCALE = 0.5;

  function makeText(str, fontSizePx, colorHex, align) {
    const obj = ctx.fontAtlas.createText(str, {
      fontSize: fontSizePx,
      color: colorHex,
      align,
    });
    obj.scale.setScalar(TEXT_SCALE);
    return obj;
  }

  function widthOf(obj) {
    const box = new Box3().setFromObject(obj);
    const size = new Vector3();
    box.getSize(size);
    return size.x || 0.01;
  }

  // ---------- CAPTION KICKER ----------
  const captionText = makeText(captionStr, 18, colors.accent, 'center');
  captionText.position.set(0, 1.15, 0);
  root.add(captionText);

  // ---------- HERO (dimensional, per-word depth) ----------
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  root.add(heroGroup);

  const heroWords = heroStr.split(' ').filter(Boolean);
  const zOffsets = [0.12, 0.0, -0.12];
  const wordMeshes = [];
  const gap = 0.14;

  heroWords.forEach((word, i) => {
    const w = makeText(word, 124, colors.paper, 'left');
    w.userData.zOffset = zOffsets[i % zOffsets.length];
    heroGroup.add(w);
    wordMeshes.push(w);
  });

  // lay words out left-to-right, then center the whole line
  let cursorX = 0;
  const widths = wordMeshes.map((w) => widthOf(w));
  wordMeshes.forEach((w, i) => {
    w.position.x = cursorX;
    w.position.z = w.userData.zOffset;
    cursorX += widths[i] + gap;
  });
  const totalWidth = Math.max(cursorX - gap, 0.01);
  wordMeshes.forEach((w) => {
    w.position.x -= totalWidth / 2;
  });

  // ---------- ACCENT UNDERLINE ----------
  const underlinePivot = new Group();
  underlinePivot.position.set(-totalWidth / 2, -0.05, 0.05);
  root.add(underlinePivot);

  const underlineGeo = new PlaneGeometry(2.6, 0.045);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new Color(colors.accent);
  underlineMat.emissive = new Color(colors.accent);
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 0.55;
  underlineMat.metalness = 0.3;
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.x = 2.6 / 2; // anchor-left: pivot at left edge
  underlinePivot.add(underline);
  underlinePivot.scale.x = 0.0001;

  // ---------- SUBHEAD ----------
  const subheadText = makeText(subheadStr, 40, '#aab2bf', 'center');
  subheadText.position.set(0, -0.65, 0.02);
  root.add(subheadText);

  // ---------- RIM / ACCENT LIGHT (node-local, per doctrine) ----------
  const rimLight = new THREE.PointLight(new Color(colors.accent), 0.9, 8, 2);
  rimLight.position.set(-1.8, -0.4, 1.6);
  root.add(rimLight);

  const fillLight = new THREE.DirectionalLight(new Color(colors.paper), 0.5);
  fillLight.position.set(2.2, 1.5, 2.0);
  root.add(fillLight);

  // ---------- INITIAL STATES (pre-entrance) ----------
  subheadText.visible = true;
  const subheadMat = subheadText.material;
  gsap.set(subheadText.position, { y: -0.65 + 0.2 });
  if (subheadMat && 'opacity' in subheadMat) {
    subheadMat.transparent = true;
    subheadMat.opacity = 0;
  }
  captionText.position.y = 1.15;

  // ---------- CINEMATIC PRIMITIVE: kinetic-text ----------
  const ktPrim = config.cinematicPrimitives?.find((p) => p.name === 'kinetic-text');
  const ktParams = ktPrim?.params ?? { staggerMs: 60, riseUnits: 0.35 };
  let ktResult = null;
  if (ctx.primitives?.['kinetic-text']) {
    ktResult = ctx.primitives['kinetic-text'](heroGroup, ktParams);
    if (ktResult) cleanupFns.push(() => ktResult.cleanup?.());
  }

  // Estimate landing time of last glyph for downstream sequencing.
  const glyphCount = heroStr.replace(/\s/g, '').length || 10;
  const staggerSec = (ktParams.staggerMs ?? 60) / 1000;
  const glyphDuration = 0.7;
  const lastGlyphLand = glyphCount * staggerSec + glyphDuration;

  // ---------- WEIGHTED SETTLE on hero group ----------
  heroGroup.scale.setScalar(1.04);
  const tl = gsap.timeline({ delay: Math.max(lastGlyphLand - 0.1, 0.1) });
  tl.to(heroGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(tl);

  // ---------- ACCENT UNDERLINE reveal ----------
  const tlUnderline = gsap.timeline({ delay: lastGlyphLand + 0.12 });
  tlUnderline.to(underlinePivot.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
  });
  timelines.push(tlUnderline);

  // ---------- SUBHEAD fade-up ----------
  const tlSubhead = gsap.timeline({ delay: lastGlyphLand + 0.2 });
  tlSubhead.to(subheadText.position, {
    y: -0.65,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  if (subheadMat && 'opacity' in subheadMat) {
    tlSubhead.to(subheadMat, {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => { subheadMat.needsUpdate = true; },
    }, 0);
  }
  timelines.push(tlSubhead);

  // ---------- CAPTION rise-in ----------
  captionText.position.y = 1.15 + 0.15;
  const captionMat = captionText.material;
  if (captionMat && 'opacity' in captionMat) {
    captionMat.transparent = true;
    captionMat.opacity = 0;
  }
  const tlCaption = gsap.timeline({ delay: 0.05 });
  tlCaption.to(captionText.position, {
    y: 1.15,
    duration: 0.6,
    ease: 'power3.out',
  }, 0);
  if (captionMat && 'opacity' in captionMat) {
    tlCaption.to(captionMat, {
      opacity: 1,
      duration: 0.6,
      ease: 'power3.out',
      onUpdate: () => { captionMat.needsUpdate = true; },
    }, 0);
  }
  timelines.push(tlCaption);

  // ---------- USERDATA ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    cleanupFns.forEach((fn) => {
      try { fn(); } catch (e) { /* noop */ }
    });

    backdropGeo.dispose();
    backdropMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();

    const disposeText = (obj) => {
      if (!obj) return;
      obj.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      });
    };
    disposeText(captionText);
    disposeText(subheadText);
    wordMeshes.forEach(disposeText);
  };

  return root;
}
